'\''1i /* Embedded subzeroclaw configuration. NULL log_dir uses $HOME/.nextvi/logs. */
static char *log_dir;
#define LOCAL 1
#define OPENROUTER 1

#if LOCAL == 1
static char *api_key = "local";
static char *endpoint = "http://127.0.0.1:8080/v1/chat/completions";
static char *request_extra = "{}";
#elif OPENROUTER == 1
static char *api_key = "YOUR_OPENROUTER_API_KEY";
static char *endpoint = "https://openrouter.ai/api/v1/chat/completions";
static char *request_extra = "{\"model\":\"PROVIDER/MODEL_ID\"}";
#endif

static int request_timeout = 120;
static int max_tool_rounds = 200;
int xgr = 2;	/* agent guardrails: anything but 2 = disabled */
int xar;	/* display returned agent reasoning (:ar) */

static char exspec_insert[] =
	"For tool i/c calls, supply text directly with literal newlines, no dot "
	"terminator or keyboard escape. Text is required.";
static char exspec_global[] =
	"Bound global command output; stop when you have enough context.";

/* Additional :exspec lines; repeat a command to append more lines. */
static struct {
	char *cmd, *text;
} conf_exspec[] = {
	{"i", exspec_insert},
	{"c", exspec_insert},
	{"p", "Cursor position is stateful; left at the range position it landed on"},
	{"p", "Keep reads small and within buffer bounds."},
	{"p", "Check the position with = and line count with $= before printing ranges."},
	{"p", "Use character ranges for long lines; stop when you have enough context."},
	{"p", ""},
	{"p", "Example: print 5 lines around current position"},
	{"p", ".-5,.+5p"},
	{"p", "Example: print first occurrence of \"int\""},
	{"p", ">int>p"},
	{"ranges", "> and < start searching from the current cursor position."},
	{"ranges", "Verify position with = command to ensure it is where intended."},
	{"=", "Check the line count with $= before printing ranges."},
	{"g", exspec_global},
	{"g!", exspec_global},
	{"!", "Bound shell output; stop when you have enough context."},
};

