+static cJSON *agent_messages;
+static unsigned long agent_epoch, agent_serial;
+static int agent_ready, agent_syncing, agent_child_status;
+static char *agent_init_error;
+static unsigned long agent_rounds;	/* tool rounds completed in the current run */
+static unsigned long agent_tool_calls;	/* cumulative ex tool calls executed */
+
+static const char agent_skills[] =
+"Inside Nextvi, use the ex tool with a JSON object whose command \n"
+"key holds an ex command.\n"
+"\n"
+"Nextvi is NOT a standard vi/ex\n"
+"\n"
+"Without an argument, exspec prints the command index with one-line descriptions.\n"
+"Given an argument, exspec prints the ex specification for a command or a topic.\n"
+"PROTECT THE CONTEXT: ALWAYS CONSULT EXSPEC WITH FOR A COMMAND NOT USED PREVIOUSLY.\n"
+"Do not assume. exspec is your guide.\n"
+"At a minimum, you must execute:\n"
+"exspec p\n"
+"Optional:\n"
+"exspec ranges\n"
+"\n"
+"Ex spec notation: <x> denotes a character literal, [x] an optional argument, \n"
+"{x} a required argument, and \"x\" a string. <^X> denotes Ctrl-X. Spaces \n"
+"inside a closure separate alternatives; # denotes decimal representation \n"
+"inside a closure, and x-y denotes a range. These are notation, not text to \n"
+"type; use the actual characters or values.\n"
+"\n"
+"Ex syntax: [<sep>][prefix][cmd][<pad>][args]. Use one space pad before arguments \n"
+"to avoid command-name ambiguity. Your session defaults to vis 3 (raw ex \n"
+"mode), with all ex special characters disabled: escape, separator, pathname \n"
+"expansion and shell expansion. With these defaults, command chaining is \n"
+"unavailable; use one command per tool call. No additional ex argument \n"
+"escaping is needed.\n";
+
+static cJSON *agent_msg(const char *role, const char *content)
+{
+	cJSON *m = cJSON_CreateObject();
+	cJSON_AddStringToObject(m, "role", role);
+	cJSON_AddStringToObject(m, "content", content);
+	return m;
+}
+
+static char *agent_text(struct lbuf *lb)
+{
+	sbuf_smake(sb, 256)
+	for (int i = 0; i < lbuf_len(lb); i++)
+		sbuf_str(sb, lb->ln[i])
+	sbufn_ret(sb, sb->s)
+}
+
+static int agent_writeall(int fd, const char *s, size_t n)
+{
+	while (n) {
+		ssize_t k = write(fd, s, n);
+		if (k < 0 && errno == EINTR)
+			continue;
+		if (k <= 0)
+			return -1;
+		s += k;
+		n -= k;
+	}
+	return 0;
+}
+
+static void agent_output(const char *s)
+{
+	agent_writeall(STDOUT_FILENO, s, strlen(s));
+}
+
+static int agent_save(int i)
+{
+	struct buf *b = tempbufs + i;
+	char *path = emalloc(strlen(b->path) + 16);
+	int fd, ret = -1;
+	sprintf(path, "%s.XXXXXX", b->path);
+	fd = mkstemp(path);
+	if (fd >= 0) {
+		ret = lbuf_wr(b->lb, fd, 0, lbuf_len(b->lb));
+		if (fsync(fd))
+			ret = -1;
+		if (close(fd))
+			ret = -1;
+		if (!ret && rename(path, b->path))
+			ret = -1;
+		if (!ret)
+			b->mtime = mtime(b->path);
+		unlink(path);
+	}
+	free(path);
+	return ret;
+}
+
+static void agent_sync(struct lbuf *lb)
+{
+	if (!agent_ready || agent_syncing)
+		return;
+	for (int i = 3; i < 5; i++) {
+		if (tempbufs[i].lb != lb)
+			continue;
+		agent_syncing = 1;
+		if (agent_save(i))
+			ex_print("agent write failed; buffer text retained",
+				msg_ft)
+		agent_syncing = 0;
+	}
+}
+
+static int agent_mkdir(char *path)
+{
+	struct stat st;
+	for (char *p = path + 1; ; p++) {
+		char c = *p;
+		if (c && c != '/')
+			continue;
+		*p = 0;
+		int failed = (mkdir(path, 0700) && errno != EEXIST) ||
+			stat(path, &st) || !S_ISDIR(st.st_mode);
+		*p = c;
+		if (failed)
+			return -1;
+		if (!c)
+			return 0;
+	}
+}
+
+static void agent_history(int edited)
+{
+	char *s = agent_text(tempbufs[4].lb);
+	cJSON_Delete(agent_messages);
+	agent_messages = cJSON_CreateArray();
+	cJSON_AddItemToArray(agent_messages, agent_msg("system", s));
+	free(s);
+	if (edited) {
+		s = agent_text(tempbufs[3].lb);
+		cJSON_AddItemToArray(agent_messages, agent_msg("user", s));
+		free(s);
+	}
+}
+
+static void agent_init(void)
+{
+	const char *home = getenv("HOME");
+	char *dir, *path;
+	temp_open(3, "/conversation/", _ft);
+	temp_open(4, "/skills/", _ft);
+	lbuf_edit(tempbufs[4].lb, (char *)agent_skills, 0, 0, 0, 0);
+	lbuf_saved(tempbufs[4].lb, 1);
+	if ((!log_dir && (!home || !*home)) || (log_dir && !*log_dir)) {
+		agent_init_error = "agent log directory is not configured";
+		return;
+	}
+	dir = emalloc(strlen(log_dir ? log_dir : home) + 64);
+	if (log_dir)
+		strcpy(dir, log_dir);
+	else
+		sprintf(dir, "%s/.nextvi/logs", home);
+	if (agent_mkdir(dir))
+		goto fail;
+	strcat(dir, "/session-XXXXXX");
+	if (!mkdtemp(dir))
+		goto fail;
+	/* Absolute paths survive :cd during the session. */
+	if (*dir != '/') {
+		char *cwd = getcwd(NULL, 0);
+		if (!cwd)
+			goto fail;
+		path = emalloc(strlen(cwd) + strlen(dir) + 2);
+		sprintf(path, "%s/%s", cwd, dir);
+		free(cwd);
+		free(dir);
+		dir = path;
+	}
+	for (int i = 3; i < 5; i++) {
+		path = emalloc(strlen(dir) + 32);
+		sprintf(path, "%s/%s", dir, i == 3 ? "conversation" : "skills");
+		free(tempbufs[i].path);
+		tempbufs[i].path = path;
+		tempbufs[i].plen = strlen(path);
+		if (agent_save(i))
+			goto fail;
+	}
+	agent_ready = 1;
+	agent_history(0);
+	free(dir);
+	return;
+fail:
+	free(dir);
+	agent_init_error = "cannot create agent session files";
+}
+
+static void agent_log(const char *role, const char *text)
+{
+	sbuf_smake(sb, 256)
+	sbuf_str(sb, role)
+	sbuf_chr(sb, '\n')
+	sbuf_str(sb, text);
+	if (sb->s[sb->s_n-1] != '\n')
+		sbuf_chr(sb, '\n')
+	sbuf_chr(sb, '\n')
+	sbuf_nul(sb)
+	agent_output(sb->s);
+	tempbufs[3].lb->useq++;
+	lbuf_edit(tempbufs[3].lb, sb->s, lbuf_len(tempbufs[3].lb),
+		lbuf_len(tempbufs[3].lb), 0, 0);
+	tempbufs[3].lb->useq++;
+	free(sb->s);
+}
+
+static void agent_key(int c)
+{
+	if (c == TK_CTL('c'))
+		agent_cancel = 1;
+	if (c == 27 && !agent_cancel)
+		agent_cancel = 2;
+	if (c == TK_CTL('o'))
+		agent_pause = 1;
+	if (c == TK_CTL('l'))
+		term_winch = 1;
+}
+
+static int agent_boundary(void)
+{
+	if (agent_input_blocked)
+		return 1;
+	preserve(int, agent_tool, agent_tool = 0;)
+	while (tibuf_pos < tibuf_cnt)
+		agent_key(term_read(0));
+	while (poll(&term_ufd, 1, 0) > 0 && term_ufd.revents & POLLIN)
+		agent_key(term_read(0));
+	restore(agent_tool)
+	return agent_cancel || agent_pause;
+}
+
+static void agent_capture_add(const char *s, int n)
+{
+	if (xgr == 2)
+		n = MIN(n, MAX(0, 4097 - agent_capture->s_n));
+	sbuf_mem(agent_capture, s, n)
+}
+
+/* Keep one excess byte to detect truncated output; continue draining the pipe. */
+/* Use file-backed stdin; poll output and terminal together. */
+static sbuf *agent_process(char **argv, sbuf *input, int *status, int http,
+	int limited)
+{
+	FILE *in = tmpfile();
+	struct pollfd fds[2];
+	int output[2], pid, done = 0, st = 0, killed = 0;
+	char buf[4097];
+	sbuf *sb;
+	if (!in)
+		return NULL;
+	if (input && agent_writeall(fileno(in), input->s, input->s_n)) {
+		fclose(in);
+		return NULL;
+	}
+	rewind(in);
+	if (pipe(output)) {
+		fclose(in);
+		return NULL;
+	}
+	pid = fork();
+	if (!pid) {
+		setsid();
+		dup2(fileno(in), STDIN_FILENO);
+		dup2(output[1], STDOUT_FILENO);
+		dup2(output[1], STDERR_FILENO);
+		close(output[0]);
+		close(output[1]);
+		fclose(in);
+		execvp(argv[0], argv);
+		_exit(127);
+	}
+	fclose(in);
+	close(output[1]);
+	if (pid < 0) {
+		close(output[0]);
+		return NULL;
+	}
+	fds[0].fd = output[0];
+	fds[0].events = POLLIN;
+	fds[1] = term_ufd;
+	sbuf_make(sb, 4096)
+	while (!done || fds[0].fd >= 0) {
+		if ((agent_cancel || (http && agent_pause)) && !killed) {
+			kill(-pid, SIGKILL);
+			killed = 1;
+		}
+		int n = poll(fds, 2, 100);
+		if (n < 0 && errno != EINTR) {
+			agent_cancel = 1;
+			continue;
+		}
+		if (fds[0].fd >= 0 &&
+				fds[0].revents & (POLLIN | POLLHUP | POLLERR)) {
+			int nr = read(fds[0].fd, buf, sizeof(buf)-1);
+			if (nr > 0) {
+				if (limited)
+					nr = MIN(nr, MAX(0, 4097 - sb->s_n));
+				sbuf_mem(sb, buf, nr)
+			} else if (!nr || errno != EINTR) {
+				close(fds[0].fd);
+				fds[0].fd = -1;
+			}
+		}
+		if (fds[1].revents & POLLIN) {
+			preserve(int, agent_tool, agent_tool = 0;)
+			agent_key(term_read(0));
+			restore(agent_tool)
+		}
+		if (fds[1].revents & (POLLHUP | POLLERR | POLLNVAL)) {
+			agent_cancel = 1;
+			fds[1].fd = -1;
+		}
+		if (!done)
+			done = waitpid(pid, &st, WNOHANG) == pid;
+	}
+	*status = WIFEXITED(st) ? WEXITSTATUS(st) : 128 + WTERMSIG(st);
+	sbufn_ret(sb, sb)
+}
+
+static sbuf *agent_shell(char *cmd, sbuf *input, int oproc, int *status)
+{
+	char *sh = getenv("SHELL"),
+	     *argv[] = {sh && *sh ? sh : "sh",
+		xish ? "-i" : "-c", xish ? "-c" : cmd,
+		xish ? cmd : NULL};
+	int st;
+	sbuf *out = agent_process(argv, input, &st, 0, !oproc && xgr == 2);
+	if (!out) {
+		agent_child_status = 1;
+		return NULL;
+	}
+	if (status)
+		*status = st;
+	if (st)
+		agent_child_status = st;
+	if (agent_capture)
+		agent_capture_add(out->s, out->s_n);
+	return out;
+}
+
+static void agent_http_failure(char *body)
+{
+	cJSON *root = body ? cJSON_ParseWithOpts(body, NULL, 0) : NULL;
+	cJSON *error = cJSON_GetObjectItem(root, "error");
+	cJSON *message = cJSON_GetObjectItem(error, "message");
+	if (cJSON_IsString(message) && *message->valuestring)
+		agent_log("RESULT", message->valuestring);
+	else
+		agent_log("RESULT", "HTTP request failed");
+	cJSON_Delete(root);
+}
+
+static cJSON *agent_config(void)
+{
+	cJSON *req = cJSON_ParseWithOpts(request_extra, NULL, 1);
+	if (!cJSON_IsObject(req) || !api_key || !*api_key ||
+			strpbrk(api_key, "\r\n") || !endpoint ||
+			(strncmp(endpoint, "http://", 7) &&
+			strncmp(endpoint, "https://", 8)) ||
+			request_timeout <= 0 || max_tool_rounds <= 0) {
+		cJSON_Delete(req);
+		return NULL;
+	}
+	/* Remove duplicates so providers cannot interpret a shadow value. */
+	const char *owned[] = {"messages", "tools", "stream"};
+	for (int i = 0; i < LEN(owned); i++)
+		while (cJSON_GetObjectItem(req, owned[i]))
+			cJSON_DeleteItemFromObject(req, owned[i]);
+	return req;
+}
+
+static char *agent_http(cJSON *req, int *st)
+{
+	char hdrpath[] = "/tmp/nextvi-header-XXXXXX", timeout[32], hdrarg[80];
+	int fd = mkstemp(hdrpath);
+	sbuf *out = NULL;
+	sbuf_smake(hdr, 128)
+	sbuf_str(hdr, "Authorization: Bearer ")
+	sbuf_str(hdr, api_key)
+	sbuf_chr(hdr, '\n')
+	if (fd < 0)
+		goto ret;
+	if (agent_writeall(fd, hdr->s, hdr->s_n)) {
+		close(fd);
+		goto ret;
+	}
+	close(fd);
+	snprintf(timeout, sizeof(timeout), "%d", request_timeout);
+	sprintf(hdrarg, "@%s", hdrpath);
+	char *argv[] = {
+		"curl", "--disable", "--silent", "--show-error",
+		"--fail-with-body", "--max-time", timeout, "--header", hdrarg,
+		"--header", "Content-Type: application/json",
+		"--data-binary", "@-", "--url", endpoint, NULL
+	};
+	sbuf body;
+	body.s = cJSON_PrintUnformatted(req);
+	body.s_n = strlen(body.s);
+	out = agent_process(argv, &body, st, 1, 0);
+	free(body.s);
+ret:
+	unlink(hdrpath);
+	free(hdr->s);
+	if (!out) {
+		*st = -1;
+		return NULL;
+	}
+	char *s = out->s;
+	free(out);
+	return s;
+}
+
+static char *agent_snapshot(char *loc)
+{
+	int beg = 0, end = lbuf_len(xb), o1 = -1, o2 = -1;
+	char info[160];
+	sbuf text;
+	if (loc && ex_region(loc, &beg, &end, &o1, &o2)) {
+		if (lbuf_len(xb) || strcmp(loc, "%"))
+			return NULL;
+		beg = end = 0;
+	}
+	int last = MAX(0, end-1);
+	if (o1 >= 0)
+		o1 = MIN(o1, lbuf_get(xb, beg) ?
+			uc_slen(lbuf_get(xb, beg)) : 0);
+	if (o2 >= 0)
+		o2 = MIN(o2, lbuf_get(xb, last) ?
+			uc_slen(lbuf_get(xb, last)) : 0);
+	int endoff = o2 >= 0 ? o2 :
+		(lbuf_get(xb, last) ? uc_slen(lbuf_get(xb, last)) : 0);
+	sbuf_smake(sb, 256)
+	snprintf(info, sizeof(info), "Editor snapshot\nbuffer %d\nname ",
+		istempbuf(ex_buf) ?
+			(int)(tempbufs-ex_buf-1) : (int)(ex_buf-bufs));
+	sbuf_str(sb, info)
+	sbuf_str(sb, xb_path)
+	snprintf(info, sizeof(info),
+		"\nrange %d;%d,%d;%d (end character exclusive)\n",
+		end ? beg+1 : 0, MAX(o1, 0), end, endoff);
+	sbuf_str(sb, info)
+	lbuf_region(xb, &text, beg, MAX(o1, 0), last, o2);
+	sbuf_str(sb, text.s)
+	free(text.s);
+	sbufn_ret(sb, sb->s)
+}
+
+static void agent_resize(void)
+{
+	struct winsize win;
+	if (!ioctl(term_ufd.fd, TIOCGWINSZ, &win)) {
+		if (win.ws_col)
+			xcols = win.ws_col;
+		if (win.ws_row)
+			xrows = win.ws_row;
+	}
+	term_winch = 0;
+	term_resized++;
+}
+
+/* Reconstruct only a screenful, never replay the entire log to scrollback. */
+static void agent_redraw(const char *draft)
+{
+	char *log = agent_text(tempbufs[3].lb);
+	sbuf_smake(sb, 256)
+	sbuf_str(sb, log);
+	if (draft)
+		sbuf_str(sb, draft);
+	sbuf_nul(sb)
+	int cap = MAX(2, xrows), *starts = emalloc(sizeof(int) * cap);
+	int rows = 1, col = 0;
+	starts[0] = 0;
+	for (int i = 0; i < sb->s_n; ) {
+		char *s = sb->s+i;
+		int n = uc_len(s), newline = *s == '\n', code;
+		uc_code(code, s, n)
+		col += *s == '\t' ? 8 - col % 8 : MAX(0, uc_wid(code));
+		i += MAX(1, n);
+		if (newline || col >= MAX(1, xcols)) {
+			starts[rows++ % cap] = i;
+			col = 0;
+		}
+	}
+	int start = starts[MAX(0, rows - MAX(1, xrows-2)) % cap];
+	term_clean();
+	agent_output(sb->s + start);
+	free(starts);
+	free(log);
+	free(sb->s);
+}
+
+/* Recurse from the ex-style conversation into vi, preserving caller state. */
+static void agent_editor(void)
+{
+	preserve(int, xvis, xvis = (xvis | 2) & ~1;)
+	preserve(int, agent_tool, agent_tool = 0;)
+	preserve(sbuf *, agent_capture, agent_capture = NULL;)
+	preserve(int, agent_cancel, agent_cancel = 0;)
+	preserve(int, agent_pause, agent_pause = 0;)
+	preserve(int, xesc, xesc = '\\';)
+	preserve(int, xsep, xsep = ':';)
+	preserve(int, xexp, xexp = '%';)
+	preserve(int, xexe, xexe = '!';)
+	led_modeswap();
+	restore(xexe)
+	restore(xexp)
+	restore(xsep)
+	restore(xesc)
+	restore(agent_pause)
+	restore(agent_cancel)
+	restore(agent_capture)
+	restore(agent_tool)
+	restore(xvis)
+}
+
+static void agent_refresh(void)
+{
+	char *s = agent_snapshot(NULL);
+	cJSON_AddItemToArray(agent_messages, agent_msg("user", s));
+	agent_log("USER", s);
+	free(s);
+}
+
+static void agent_sequence(void)
+{
+	for (int i = 0; i < xbufcur; i++)
+		bufs[i].lb->useq += xseq;
+	for (int i = 0; i < LEN(tempbufs); i++)
+		tempbufs[i].lb->useq += xseq;
+}
+
+static void agent_run(const char *input)
+{
+	unsigned long serial = ++agent_serial, epoch = agent_epoch;
+	cJSON *req, *root, *message, *calls, *tc, *text;
+	char *body;
+	int st;
+	agent_cancel = agent_pause = 0;
+	agent_rounds = 0;
+	cJSON_AddItemToArray(agent_messages, agent_msg("user", input));
+	agent_log("USER", input);
+	for (int round = 0; ; ) {
+		req = agent_config();
+		if (!req) {
+			agent_log("RESULT", "invalid agent configuration");
+			return;
+		}
+		cJSON_AddItemReferenceToObject(req, "messages", agent_messages);
+		cJSON_AddItemToObject(req, "tools",
+			cJSON_Parse("[{\"type\":\"function\",\"function\":{"
+			"\"name\":\"ex\",\"description\":"
+			"\"Execute an ex command in nextvi\","
+			"\"parameters\":{\"type\":\"object\",\"properties\":{"
+			"\"command\":{\"type\":\"string\"}},"
+			"\"required\":[\"command\"],"
+			"\"additionalProperties\":false}}}]"));
+		cJSON_AddBoolToObject(req, "stream", 0);
+		body = agent_http(req, &st);
+		cJSON_Delete(req);
+		if (agent_cancel) {
+			free(body);
+			if (agent_cancel != 2)
+				agent_log("RESULT", "cancelled");
+			return;
+		}
+		if (agent_pause) {
+			free(body);
+			agent_editor();
+			agent_redraw(NULL);
+			agent_pause = 0;
+			if (serial != agent_serial ||
+					epoch != agent_epoch || xquit)
+				return;
+			agent_log("RESULT",
+				"response skipped after recursive editing");
+			agent_refresh();
+			continue;
+		}
+		if (st || !body) {
+			agent_http_failure(body);
+			free(body);
+			return;
+		}
+		root = cJSON_ParseWithOpts(body, NULL, 1);
+		free(body);
+		text = cJSON_GetObjectItem(
+			cJSON_GetObjectItem(root, "error"), "message");
+		message = cJSON_GetObjectItem(cJSON_GetArrayItem(
+			cJSON_GetObjectItem(root, "choices"), 0), "message");
+		calls = cJSON_GetObjectItem(message, "tool_calls");
+		cJSON *role = cJSON_GetObjectItem(message, "role");
+		cJSON *content = cJSON_GetObjectItem(message, "content");
+		int valid = cJSON_IsObject(message) && cJSON_IsString(role) &&
+			!strcmp(role->valuestring, "assistant") &&
+			(!content || cJSON_IsNull(content) ||
+			 cJSON_IsString(content)) &&
+			(!calls || cJSON_IsArray(calls)) &&
+			(cJSON_IsString(content) || cJSON_GetArraySize(calls));
+		cJSON_ArrayForEach(tc, calls) {
+			cJSON *id = cJSON_GetObjectItem(tc, "id");
+			if (!cJSON_IsString(id) || !*id->valuestring)
+				valid = 0;
+			for (cJSON *prev = calls->child; prev != tc;
+					prev = prev->next) {
+				cJSON *pid = cJSON_GetObjectItem(prev, "id");
+				if (cJSON_IsString(id) && cJSON_IsString(pid) &&
+					!strcmp(id->valuestring,
+						pid->valuestring))
+					valid = 0;
+			}
+		}
+		if (!valid || cJSON_GetObjectItem(root, "error")) {
+			agent_log("RESULT", cJSON_IsString(text) ?
+				text->valuestring :
+				"malformed assistant response");
+			cJSON_Delete(root);
+			return;
+		}
+		/* Complete pairs before recursive editing or submissions. */
+		cJSON_AddItemToArray(agent_messages,
+			cJSON_Duplicate(message, 1));
+		if (xar) {
+			cJSON *reasoning = cJSON_GetObjectItem(message,
+				"reasoning_content");
+			if (!cJSON_IsString(reasoning) || !*reasoning->valuestring)
+				reasoning = cJSON_GetObjectItem(message, "reasoning");
+			if (cJSON_IsString(reasoning) && *reasoning->valuestring)
+				agent_log("REASONING", reasoning->valuestring);
+		}
+		if (cJSON_IsString(content))
+			agent_log("ASSISTANT", content->valuestring);
+		int base = cJSON_GetArraySize(agent_messages), index = 0;
+		cJSON_ArrayForEach(tc, calls) {
+			cJSON *result = agent_msg("tool",
+				"skipped: pending execution");
+			cJSON_AddStringToObject(result, "tool_call_id",
+				cJSON_GetObjectItem(tc, "id")->valuestring);
+			cJSON_AddItemToArray(agent_messages, result);
+		}
+		cJSON_ArrayForEach(tc, calls) {
+			cJSON *fn = cJSON_GetObjectItem(tc, "function");
+			cJSON *name = cJSON_GetObjectItem(fn, "name"),
+			      *args = cJSON_GetObjectItem(fn, "arguments");
+			cJSON *parsed = cJSON_IsString(args) ?
+				cJSON_ParseWithOpts(args->valuestring,
+					NULL, 1) : NULL;
+			cJSON *command = cJSON_GetObjectItem(parsed, "command");
+			char *err = NULL;
+			agent_child_status = 0;
+			sbuf_smake(out, 256)
+			sbuf_smake(result, 256)
+			agent_boundary();
+			agent_log("EX", cJSON_IsString(command) ?
+				command->valuestring : "invalid tool call");
+			if (agent_cancel || agent_pause ||
+					round == max_tool_rounds)
+				err = "skipped: execution cancelled, "
+					"suspended, or round limit reached";
+			else if (!cJSON_IsString(name) ||
+					strcmp(name->valuestring, "ex"))
+				err = "unknown tool (expected ex)";
+			else if (!cJSON_IsString(command) ||
+					!*command->valuestring)
+				err = "ex requires a nonempty command string";
+			else {
+				int savedquit = xquit, savedqprop = xqprop;
+				agent_input_blocked = 0;
+				agent_tool = 1;
+				agent_capture = out;
+				agent_child_status = 0;
+				agent_sequence();
+				err = ex_exec(command->valuestring);
+				agent_tool_calls++;
+				agent_sequence();
+				if (xgr == 2 && out->s_n > 4096) {
+					sbuf_cut(out, 0)
+					sbufn_str(out, "4096 byte context protection limit exceeded: use gr 0 to disable guardrail for 1 turn")
+				} else if (xgr >= 0 && xgr < 2)
+					xgr++;
+				agent_capture = NULL;
+				agent_tool = 0;
+				if (agent_input_blocked) {
+					xquit = savedquit;
+					xqprop = savedqprop;
+					agent_input_blocked = 0;
+					err = "interactive input unavailable during agent execution";
+				}
+			}
+			if (agent_cancel)
+				sbuf_str(result, "cancelled\n")
+			else if (agent_pause)
+				sbuf_str(result,
+					"suspended; remaining commands "
+					"skipped\n")
+			else {
+				char status[64];
+				snprintf(status, sizeof(status), "status %d\n",
+					agent_child_status ?
+						agent_child_status : !!err);
+				sbuf_str(result, status)
+			}
+			if (err && err != xuerr) {
+				sbuf_str(result, err)
+				sbuf_chr(result, '\n')
+			}
+			sbuf_mem(result, out->s, out->s_n)
+			sbuf_nul(result)
+			cJSON_ReplaceItemInObject(cJSON_GetArrayItem(
+				agent_messages, base + index++),
+				"content", cJSON_CreateString(result->s));
+			if (agent_cancel != 2)
+				agent_log("RESULT", result->s);
+			cJSON_Delete(parsed);
+			free(out->s);
+			free(result->s);
+		}
+		int has_calls = cJSON_GetArraySize(calls);
+		cJSON_Delete(root);
+		if (agent_cancel)
+			return;
+		if (agent_pause) {
+			agent_editor();
+			agent_redraw(NULL);
+			agent_pause = 0;
+			if (serial != agent_serial ||
+					epoch != agent_epoch || xquit)
+				return;
+			agent_refresh();
+		}
+		agent_rounds = round;
+		if (!has_calls)
+			return;
+		if (round++ == max_tool_rounds) {
+			agent_log("RESULT",
+				"maximum tool rounds reached; "
+				"submit to continue");
+			return;
+		}
+	}
+}
+
+/* Print agent context usage and session statistics. */
+static void *ec_aco(char *loc, char *cmd, char *arg)
+{
+	char msg[200];
+	int counts[4] = {0, 0, 0, 0};
+	unsigned long sums[4] = {0, 0, 0, 0};
+	const char *names[4] = {"system", "user", "assistant", "tool"};
+	cJSON *m;
+	ex_print("agent context usage", msg_ft)
+	if (!agent_ready) {
+		ex_print(agent_init_error ? agent_init_error :
+			"agent session is not running", msg_ft)
+		return NULL;
+	}
+	snprintf(msg, sizeof(msg), "state      ready, run %lu, epoch %lu",
+		agent_serial, agent_epoch);
+	ex_print(msg, msg_ft)
+	snprintf(msg, sizeof(msg), "activity   %lu tool calls, %lu rounds this run",
+		agent_tool_calls, agent_rounds);
+	ex_print(msg, msg_ft)
+	if (agent_messages) {
+		cJSON_ArrayForEach(m, agent_messages) {
+			cJSON *role = cJSON_GetObjectItem(m, "role");
+			cJSON *content = cJSON_GetObjectItem(m, "content");
+			int r = 0;
+			if (cJSON_IsString(role)) {
+				if (!strcmp(role->valuestring, "user"))
+					r = 1;
+				else if (!strcmp(role->valuestring, "assistant"))
+					r = 2;
+				else if (!strcmp(role->valuestring, "tool"))
+					r = 3;
+			}
+			counts[r]++;
+			if (cJSON_IsString(content))
+				sums[r] += strlen(content->valuestring);
+		}
+		char *json = cJSON_PrintUnformatted(agent_messages);
+		snprintf(msg, sizeof(msg), "context    %d messages, %ld bytes payload",
+			cJSON_GetArraySize(agent_messages),
+			json ? (long)strlen(json) : 0);
+		ex_print(msg, msg_ft)
+		free(json);
+		for (int r = 0; r < 4; r++) {
+			snprintf(msg, sizeof(msg), "%-9s  %d msgs, %ld bytes",
+				names[r], counts[r], (long)sums[r]);
+			ex_print(msg, msg_ft)
+		}
+	} else
+		ex_print("context    no conversation yet", msg_ft)
+	char *s = agent_text(tempbufs[3].lb);
+	snprintf(msg, sizeof(msg), "log        %d lines, %ld bytes",
+		lbuf_len(tempbufs[3].lb), (long)strlen(s));
+	ex_print(msg, msg_ft)
+	free(s);
+	s = agent_text(tempbufs[4].lb);
+	snprintf(msg, sizeof(msg), "skills     %d lines, %ld bytes",
+		lbuf_len(tempbufs[4].lb), (long)strlen(s));
+	ex_print(msg, msg_ft)
+	free(s);
+	snprintf(msg, sizeof(msg), "capture    %ld bytes in current tool output",
+		agent_capture ? (long)agent_capture->s_n : 0);
+	ex_print(msg, msg_ft)
+	snprintf(msg, sizeof(msg), "limits     %d rounds max, %d sec timeout, guardrail %d",
+		max_tool_rounds, request_timeout, xgr);
+	ex_print(msg, msg_ft)
+	snprintf(msg, sizeof(msg), "session    %s", tempbufs[3].path);
+	ex_print(msg, msg_ft)
+	return NULL;
+}
+
+static void *ec_agent(char *loc, char *cmd, char *arg)
+{
+	char *scope = NULL;
+	int key, prefix = 2, savedvis = xvis, term_owned = !term_sbuf;
+	cJSON *config;
+	unsigned long epoch;
+	if (cmd[1] && (*loc || *arg))
+		return "agent restart rejects ranges and arguments";
+	if (agent_init_error)
+		return agent_init_error;
+	if (!(config = agent_config()))
+		return "invalid agent configuration";
+	cJSON_Delete(config);
+	if (*loc && !(scope = agent_snapshot(loc)))
+		return xrerr;
+	if (cmd[1]) {
+		agent_epoch++;
+		agent_serial++;
+		if (cmd[1] == '!') {
+			struct lbuf *lb = tempbufs[3].lb;
+			agent_syncing = 1;
+			lbuf_edit(lb, NULL, 0, lbuf_len(lb), 0, 0);
+			lbuf_saved(lb, 1);
+			agent_syncing = 0;
+			int fd = open(tempbufs[3].path, O_WRONLY | O_TRUNC);
+			if (fd < 0 || close(fd))
+				ex_print("agent reset write failed; "
+					"buffer cleared", msg_ft)
+			tempbufs[3].row = tempbufs[3].off = tempbufs[3].top = 0;
+			if (ex_buf == tempbufs+3) {
+				exbuf_load(ex_buf)
+			}
+		}
+		agent_history(cmd[1] == '~');
+	}
+	epoch = agent_epoch;
+	if (term_owned)
+		term_init();
+	if (!(savedvis & 2))
+		agent_output("\n");
+	xvis = 3;
+	preserve(int, xesc, xesc = 0;)
+	preserve(int, xsep, xsep = 0;)
+	preserve(int, xexp, xexp = 0;)
+	preserve(int, xexe, xexe = 0;)
+	sbuf_smake(draft, 128)
+	sbuf_smake(line, 128)
+	sbuf_str(line, "> ")
+	ins_state is;
+	ins_init(is)
+	if (*arg)
+		term_push(arg, strlen(arg));
+	while (!xquit && epoch == agent_epoch) {
+		preserve(int, ftidx,)
+		preserve(int, xvis, xvis = (xvis | 2) & ~1;)
+		syn_setft(_ft);
+		key = led_prompt(line, NULL, &xkmap, &is, prefix, 2|LED_AGENT);
+		restore(xvis)
+		restore(ftidx)
+		if (key == TK_CTL('c') || !key)
+			break;
+		if (key == TK_CTL('o')) {
+			agent_editor();
+			if (epoch != agent_epoch)
+				break;
+			ins_init(is)
+			agent_redraw(draft->s_n ? draft->s : NULL);
+		} else if (key == TK_CTL('b')) {
+			if (epoch != agent_epoch)
+				break;
+			agent_redraw(draft->s_n ? draft->s : NULL);
+		} else if (key == TK_CTL('l')) {
+			agent_resize();
+			agent_redraw(draft->s_n ? draft->s : NULL);
+		} else if (key == '\n' || key == 27) {
+			sbuf_str(draft, line->s + prefix)
+			if (key == '\n') {
+				sbufn_chr(draft, '\n')
+				agent_output("\n");
+			} else if (draft->s_n || scope) {
+				if (scope) {
+					sbuf_chr(draft, '\n')
+					sbuf_str(draft, scope)
+					free(scope);
+					scope = NULL;
+				}
+				sbuf_nul(draft)
+				agent_output("\n");
+				agent_run(draft->s);
+				sbufn_cut(draft, 0)
+				if (agent_cancel == 1)
+					break;
+				agent_cancel = 0;
+			}
+			prefix = key == '\n' ? 0 : 2;
+			sbufn_cut(line, 0)
+			if (prefix)
+				sbuf_str(line, "> ")
+			ins_init(is)
+		}
+	}
+	agent_output("\n");
+	free(scope);
+	free(draft->s);
+	free(line->s);
+	restore(xexe)
+	restore(xexp)
+	restore(xsep)
+	restore(xesc)
+	xvis = savedvis;
+	if (term_owned)
+		term_done();
+	syn_setft(xb_ft);
+	return NULL;
+}
